import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def col_to_idx(ref):
    letters = ''.join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - ord('A') + 1)
    return idx

def row_num(ref):
    return int(''.join(ch for ch in ref if ch.isdigit()))

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Archive contents:", names)

    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
              for s in wb_root.find('m:sheets', NS)]

    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {r.get('Id'): r.get('Target') for r in rels_root}

    for name, rid in sheets:
        target = rel_map[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target
        path = target
        root = ET.fromstring(z.read(path))
        print(f"\n--- Sheet: {name} ---")
        rows = {}
        for c in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
            ref = c.get('r')
            r = row_num(ref)
            t = c.get('t')
            v = c.find('m:v', NS)
            val = None
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif v is not None:
                val = v.text
            else:
                isn = c.find('m:is', NS)
                if isn is not None:
                    val = ''.join(tt.text or '' for tt in isn.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            rows.setdefault(r, {})[col_to_idx(ref)] = (ref, val)
        for r in sorted(rows):
            cells = sorted(rows[r].items())
            print(r, [(ref, val) for _, (ref, val) in cells])

